     "code": "Shape = make_class(\"Shape\", None, {\n    \"area\": lambda self: 0,\n    \"describe\": lambda self: f\"{get_field(self, 'kind')} with area {send(self, 'area')}\",\n})\nRect = make_class(\"Rect\", Shape, {\n    \"area\": lambda self: get_field(self, \"w\") * get_field(self, \"h\"),\n    \"perimeter\": lambda self: 2 * (get_field(self, \"w\") + get_field(self, \"h\")),\n})\nSquare = make_class(\"Square\", Rect, {\n    \"describe\": lambda self: \"a square: \" + super_send(Square, self, \"describe\"),\n    \"side\": lambda self: get_field(self, \"w\"),\n})\nr = new(Rect, kind=\"rect\", w=2, h=3)\nsq = new(Square, kind=\"square\", w=4, h=4)\n\nassert send(sq, \"describe\") == \"a square: square with area 16\", send(sq, \"describe\")\nassert send(sq, \"side\") == 4 and send(sq, \"perimeter\") == 16\n\ntry:\n    send(r, 'side')\nexcept AttributeError:\n    pass\nelse:\n    raise AssertionError(\"expected AttributeError from send(r, 'side')\")\n"
